package com.example.billing.api;import static com.example.billing.api.Contracts.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<ApiError> argument(IllegalArgumentException e){return ResponseEntity.badRequest().body(new ApiError("invalid_request",e.getMessage()));}}
